  ('la-pt', 'la-t022', 'frase', 'A1', array['trecho']::text[], null, 'b7c44a0e', array['Odeias e amas. Por que fazes isso, talvez eu pergunte.', 'Odeio e amo. Por que fazes isso, talvez eu pergunte.', 'Odeio e amo. Por que faço isso, talvez perguntes.', 'Odeio o amor. Por que faço isso, talvez perguntes.', 'Odiei e amei. Por que fiz isso, talvez perguntes.']::text[]),
  ('la-pt', 'la-t023', 'frase', 'A1', array['trecho']::text[], null, '9f945427', array['Não sabes, mas sentes que acontece e te torturas.', 'Não sabia, mas sentia que acontecia e me torturava.', 'Não sei, mas sinto que acontece e me torturo.', 'Não sei, mas sinto que faço e torturo.', 'Sei, mas não sinto que acontece e me torturo.']::text[]),
  ('la-pt', 'la-t024', 'frase', 'A1', array['trecho']::text[], null, '4994e5b3', array['A rainha do céu se alegrou, aleluia.', 'Rainha do céu, alegra-te, aleluia.', 'Rainha, alegra o céu, aleluia.', 'Rainha, o céu se alegra, aleluia.', 'Rainhas do céu, alegrai-vos, aleluia.']::text[]),
  ('la-pt', 'la-t025', 'frase', 'A1', array['trecho']::text[], null, 'c3d869aa', array['Porque aquele que mereces trazer, aleluia.', 'Porque aquele que mereceste trazer, aleluia.', 'Porque aquele que merecestes trazer, aleluia.', 'Porque aquele que te mereceu trazer, aleluia.', 'Porque mereceu trazer aquele, aleluia.']::text[]),
  ('la-pt', 'la-t026', 'frase', 'A1', array['trecho']::text[], null, '08dfea19', array['Ressuscita, como diz, aleluia.', 'Ressuscitaram, como disseram, aleluia.', 'Ressuscitará, como disse, aleluia.', 'Ressuscitei, como disse, aleluia.', 'Ressuscitou, como disse, aleluia.']::text[]),
  ('la-pt', 'la-t027', 'frase', 'A1', array['trecho']::text[], null, 'c7474c45', array['Deus roga por nós, aleluia.', 'Roga a Deus por nós, aleluia.', 'Roga a nós por Deus, aleluia.', 'Rogai a Deus por nós, aleluia.', 'Rogou a Deus por nós, aleluia.']::text[]),
  ('la-pt', 'la-t028', 'frase', 'A2', array['trecho']::text[], null, '876208bc', array['Ao mesmo riacho o lobo e o cordeiro tinham vindo,', 'Ao mesmo riacho o lobo e o cordeiro vêm,', 'Ao mesmo riacho o lobo tinha levado o cordeiro,', 'Ao mesmo riacho os lobos e os cordeiros tinham vindo,', 'O lobo e o cordeiro do mesmo riacho tinham vindo,']::text[]),
  ('la-pt', 'la-t029', 'frase', 'A2', array['trecho']::text[], null, '71e105a6', array['impelido pela sede, o lobo estava acima,', 'impelidos pela sede; mais acima estava o lobo,', 'impelidos pela sede; mais acima estavam os lobos,', 'impelidos pela sede; mais acima está o lobo,', 'impelindo a sede; mais acima estava o lobo,']::text[]),
  ('la-pt', 'la-t030', 'frase', 'A2', array['trecho']::text[], null, '386254f3', array['e muito mais abaixo o cordeiro. Então, com a goela insaciável,', 'e muito mais abaixo o cordeiro. Então, com as goelas insaciáveis,', 'e muito mais abaixo o cordeiro. Então, da goela insaciável,', 'e muito mais abaixo os cordeiros. Então, com a goela insaciável,', 'e o cordeiro, longe do inferior. Então, a goela insaciável']::text[]),
  ('la-pt', 'la-t031', 'frase', 'A2', array['trecho']::text[], null, '329693a1', array['a briga do ladrão trouxe um motivo.', 'o ladrão incitou a causa da briga.', 'o ladrão, incitado, traz um motivo de briga.', 'o ladrão, incitado, trouxe um motivo de briga.', 'os ladrões, incitados, trouxeram um motivo de briga.']::text[]),
  ('la-pt', 'la-t032', 'frase', 'A2', array['trecho']::text[], null, 'd59dfcc7', array['«Por que», diz ele, «tornas turva para mim', '«Por que», diz ele, «tornaste turva para mim', '«Por que», diz ele, «tornaste turvo para mim', '«Por que», diz ele, «torno turva para ti', '«Por que», dizem eles, «tornastes turva para mim']::text[]),
  ('la-pt', 'la-t033', 'frase', 'A2', array['trecho']::text[], null, '02bad6ff', array['a água que bebes? O lanígero, em resposta, temendo:', 'a água, enquanto bebia? O lanígero, contra o medo:', 'a água, enquanto bebo? Os lanígeros, em resposta, temendo:', 'a água, enquanto bebo?» O lanígero, em resposta, temendo:', 'as águas, enquanto bebo? O lanígero, em resposta, temendo:']::text[]),
  ('la-pt', 'la-t034', 'frase', 'A2', array['trecho']::text[], null, '53b0be36', array['«Como podes, por favor, fazer aquilo de que me queixo, lobo?', '«Como posso, por favor, fazer aquilo de que os lobos se queixam?', '«Como posso, por favor, fazer aquilo de que te queixas, lobo?', '«Como pude, por favor, fazer aquilo de que te queixas, lobo?', '«Quem pode, por favor, fazer aquilo de que te queixas, lobo?']::text[]),
  ('la-pt', 'la-t035', 'frase', 'A2', array['trecho']::text[], null, '953e08dd', array['De mim desce a água até os teus goles.', 'De ti desce a água até os meus goles.»', 'De ti descem as águas até o meu gole.', 'De ti desceu a água até os meus goles.', 'Para ti desce a água dos meus goles.']::text[]),
  ('la-pt', 'la-u126', 'frase', 'A1', array['frase de uso']::text[], 'la-p004', '4e9c748e', array['Nisso estava tudo para mim.', 'Nisso está tudo para mim.', 'Nisso está tudo para ti.', 'Nisso eu sou tudo.', 'Tudo está em mim.']::text[]),
  ('la-pt', 'la-u127', 'frase', 'A1', array['frase de uso']::text[], 'la-p008', '82afb16e', array['Prepara o caminho do Senhor.', 'Preparai o caminho do Senhor.', 'Preparai o caminho para o Senhor.', 'Preparai os caminhos do Senhor.', 'Preparou o caminho do Senhor.']::text[]),
  ('la-pt', 'la-u128', 'frase', 'A1', array['frase de uso']::text[], 'la-p012', 'cf10b4a0', array['O Senhor é o nosso Deus.', 'Senhor, nós somos o teu Deus.', 'Senhor, tu eras o nosso Deus.', 'Senhor, tu és o nosso Deus.', 'Senhor, vós sois o nosso Deus.']::text[]),
  ('la-pt', 'la-u129', 'frase', 'A1', array['frase de uso']::text[], 'la-p018', '322255da', array['e Deus os louvou.', 'e louvamos a Deus.', 'e louvaram a Deus.', 'e louvarão a Deus.', 'e louvou a Deus.']::text[]),
  ('la-pt', 'la-u130', 'frase', 'A1', array['frase de uso']::text[], 'la-p021', '8e681c5d', array['Não eras, acredita em mim.', 'Não sou, acredita em mim.', 'Não és, acredita em mim.', 'Não és, acreditai em mim.', 'Não és, acredito em ti.']::text[]),
  ('la-pt', 'la-u131', 'frase', 'A1', array['frase de uso']::text[], 'la-p022', '6d865cbb', array['Em ti esperamos, ó nossos pais.', 'Em ti esperaram os nossos pais.', 'Em ti esperarão os nossos pais.', 'Em ti esperou o nosso pai.', 'Tu esperaste nos nossos pais.']::text[]),
  ('la-pt', 'la-u132', 'frase', 'A1', array['frase de uso']::text[], 'la-p025', '3259000c', array['eu sou o dia.', 'o dia era meu.', 'o dia é meu.', 'o dia é teu.', 'os dias são meus.']::text[]),
  ('la-pt', 'la-u133', 'frase', 'A1', array['frase de uso']::text[], 'la-p026', 'd3f7f9ee', array['Venceram pelas armas, foram vencidos pelos vícios.', 'Vencerá pelas armas, será vencido pelos vícios.', 'Venceu as armas, foi vencido pelos vícios.', 'Venceu pelas armas, foi vencido pelos vícios.', 'Venceu pelas armas, venceu os vícios.']::text[]),
  ('la-pt', 'la-u134', 'frase', 'A1', array['frase de uso']::text[], 'la-p030', '20c87df0', array['pois não te venci em amor.', 'pois não te venço em amor.', 'pois não vos venço em amor.', 'pois o amor não te vence.', 'pois tu não me vences em amor.']::text[]),
  ('la-pt', 'la-u135', 'frase', 'A1', array['frase de uso']::text[], 'la-p031', 'd1b48b5d', array['não era inimigo do Amor.', 'não sou inimigo do Amor.', 'não é inimigo do Amor.', 'não é inimigo dos amores.', 'o Amor não é inimigo.']::text[]),
  ('la-pt', 'la-u137', 'frase', 'A1', array['frase de uso']::text[], 'la-p037', '54d8dd8f', array['se queres amar, ama.', 'se queres amar, sê amado.', 'se queres ser amado, ama.', 'se queres ser amado, amai.', 'se quero ser amado, amo.']::text[]),
  ('la-pt', 'la-u138', 'frase', 'A1', array['frase de uso']::text[], 'la-p045', '7eff343f', array['Também estas coisas viram os dias da minha vaidade.', 'Também verei estas coisas nos dias da minha vaidade.', 'Também vi estas coisas no dia da minha vaidade.', 'Também vi estas coisas nos dias da minha vaidade.', 'Também vi estas coisas nos dias da tua vaidade.']::text[]),
  ('la-pt', 'la-u139', 'frase', 'A1', array['frase de uso']::text[], 'la-p055', '07b7bba2', array['A tua terra abençoou o Senhor.', 'Abençoarás, Senhor, a tua terra.', 'Abençoaste, Senhor, a tua terra.', 'Abençoaste, Senhor, as tuas terras.', 'Abençoei, Senhor, a tua terra.']::text[]),
  ('la-pt', 'la-u140', 'frase', 'A1', array['frase de uso']::text[], 'la-p073', 'd8ddabff', array['a mão está no ferro.', 'o ferro estava na mão.', 'o ferro está na mão.', 'o ferro está nas mãos.', 'o ferro é a mão.']::text[]),
  ('la-pt', 'la-u141', 'frase', 'A1', array['frase de uso']::text[], 'la-p074', '6a382c35', array['ele me recomenda a eles.', 'ele os recomenda a mim.', 'ele os recomendou a mim.', 'eles os recomendam a mim.', 'eu os recomendo a ti.']::text[]),
  ('la-pt', 'la-u142', 'frase', 'A1', array['frase de uso']::text[], 'la-p075', '9958b25c', array['Onde estás tu?', 'Para onde foste tu?', 'Para onde ides vós?', 'Para onde vais tu?', 'Para onde vou eu?']::text[]),
  ('la-pt', 'la-u143', 'frase', 'A1', array['frase de uso']::text[], 'la-p088', '2aad7768', array['A glória do Senhor está no século.', 'A glória do Senhor foi para sempre.', 'A glória do Senhor seja para sempre.', 'A glória dos senhores seja para sempre.', 'O Senhor da glória seja para sempre.']::text[]),
  ('la-pt', 'la-u144', 'frase', 'A1', array['frase de uso']::text[], 'la-p093', '9d03485f', array['Ainda não cheguei ao meu tempo.', 'O meu tempo ainda não chegará.', 'O meu tempo ainda não chegou.', 'O teu tempo ainda não chegou.', 'Os meus tempos ainda não chegaram.']::text[]),
  ('la-pt', 'la-u146', 'frase', 'A1', array['frase de uso']::text[], 'la-p102', 'e063da05', array['Paga, pois, a todos a dívida:', 'Pagai, pois, a todos a dívida:', 'Pagai, pois, a todos as dívidas:', 'Pagai, pois, as dívidas de todos:', 'Pagaram, pois, a todos as dívidas:']::text[]),
  ('la-pt', 'la-u147', 'frase', 'A1', array['frase de uso']::text[], 'la-p109', '70dd122c', array['Não vieram males sobre nós.', 'Não virá o mal sobre nós.', 'Não virão males sobre nós.', 'Não virão males sobre vós.', 'Não vêm males sobre nós.']::text[]),
  ('la-pt', 'la-u149', 'frase', 'A1', array['frase de uso']::text[], 'la-p111', '935b01f0', array['A vida era longa, se era cheia;', 'A vida seria longa, se fosse cheia;', 'A vida é cheia, se é longa;', 'A vida é longa, se é cheia;', 'As vidas são longas, se são cheias;']::text[]),
  ('la-pt', 'la-u150', 'frase', 'A1', array['frase de uso']::text[], 'la-p113', 'dedcfd6c', array['Era bom para o homem não tocar mulher:', 'É bom para a mulher não tocar o homem:', 'É bom para o homem não ser tocado pela mulher:', 'É bom para o homem não tocar mulher:', 'É bom para os homens não tocar mulheres:']::text[]),
  ('la-pt', 'la-u151', 'frase', 'A1', array['frase de uso']::text[], 'la-p114', 'dfe52824', array['A recompensa é o fruto para o ventre.', 'O fruto do ventre era uma recompensa.', 'O fruto do ventre é uma recompensa.', 'O ventre do fruto é uma recompensa.', 'Os frutos do ventre são uma recompensa.']::text[]),
  ('la-pt', 'la-u152', 'frase', 'A1', array['frase de uso']::text[], 'la-p116', 'c86b3684', array['Honra o pai da tua mãe.', 'Honra o teu pai e a tua mãe.', 'Honrai o vosso pai e a vossa mãe.', 'Honrou o teu pai e a tua mãe.', 'O teu pai e a tua mãe te honram.']::text[]),
  ('la-pt', 'la-u153', 'frase', 'A1', array['frase de uso']::text[], 'la-p126', 'c0203825', array['Chegaram a tempo.', 'Chegaste a tempo.', 'Cheguei a tempo.', 'Venho a tempo.', 'Virei a tempo.']::text[]),
  ('la-pt', 'la-u154', 'frase', 'A1', array['frase de uso']::text[], 'la-p127', '495f51d9', array['Fogem e não veem o bem.', 'Fugiram e não viram o bem.', 'Fugiram e não viram os bens.', 'Fugiremos e não veremos o bem.', 'Fugiu e não viu o bem.']::text[]),
  ('la-pt', 'la-u155', 'frase', 'A1', array['frase de uso']::text[], 'la-p128', 'ce100a8c', array['Os que cantam com arte, cantem;', 'Quem canta a arte, cante;', 'Quem canta com arte, canta;', 'Quem canta com arte, cante;', 'Quem cantou com arte, cante;']::text[]),
  ('la-pt', 'la-u156', 'frase', 'A1', array['frase de uso']::text[], 'la-p129', 'eea18be6', array['Não era longo.', 'Não será longo.', 'Não sou longo.', 'Não são longos.', 'Não é longo.']::text[]),
  ('la-pt', 'la-u157', 'frase', 'A1', array['frase de uso']::text[], 'la-p130', 'ada78c11', array['Breve é o dia do homem:', 'Breves eram os dias do homem:', 'Breves são os dias do homem:', 'Breves são os dias dos homens:', 'Os dias são breves para o homem:']::text[]),
  ('la-pt', 'la-u158', 'frase', 'A1', array['frase de uso']::text[], 'la-p131', '33871928', array['Tenho boa esperança, enquanto é permitido.', 'Terei boa esperança, enquanto for permitido.', 'Teremos boa esperança, enquanto for permitido.', 'Terás boa esperança, enquanto for permitido.', 'Tive boa esperança, enquanto foi permitido.']::text[]),
  ('la-pt', 'la-u159', 'frase', 'A1', array['frase de uso']::text[], 'la-p133', 'a0e86388', array['Em mim, Senhor, esperaste;', 'Em ti, Senhor, esperaram;', 'Em ti, Senhor, esperarei;', 'Em ti, Senhor, esperei;', 'Em ti, Senhor, espero;']::text[]),
  ('la-pt', 'la-u160', 'frase', 'A1', array['frase de uso']::text[], 'la-p134', 'a19f1423', array['Pensam estas coisas, e erram:', 'Pensaram estas coisas, e erraram:', 'Pensaremos estas coisas, e erraremos:', 'Pensastes estas coisas, e errastes:', 'Pensou estas coisas, e errou:']::text[]),
  ('la-pt', 'la-u161', 'frase', 'A1', array['frase de uso']::text[], 'la-p135', '84d103ce', array['A minha mão, pois, não estava sobre ti.', 'A minha mão, pois, não está sobre ti.', 'Que a minha mão, pois, não esteja sobre ti.', 'Que a tua mão, pois, não esteja sobre mim.', 'Que as minhas mãos, pois, não estejam sobre ti.']::text[]),
  ('la-pt', 'la-u162', 'frase', 'A1', array['frase de uso']::text[], 'la-p136', '4bd9ece3', array['Creio que terei medo e, ensinado, tomarei cuidado:', 'Creio que tereis medo e, ensinados, tomareis cuidado:', 'Creio que terás medo e, ensinado, tomarás cuidado:', 'Creio que terás medo e, ensinando, tomarás cuidado:', 'Creio que tiveste medo e, ensinado, tomaste cuidado:']::text[]),
  ('la-pt', 'la-u163', 'frase', 'A1', array['frase de uso']::text[], 'la-p137', 'e9ef4051', array['Enquanto hesita, o cão o viu.', 'Enquanto hesita, os cães o veem.', 'Enquanto hesita, os cães o viram.', 'Enquanto hesita, viu os cães.', 'Enquanto hesitam, os cães o viram.']::text[]),
  ('la-pt', 'la-u164', 'frase', 'A1', array['frase de uso']::text[], 'la-p138', '9086ca7f', array['Os que sabem são sábios;', 'Quem sabe será sábio;', 'Quem sabe é sábio;', 'Quem sabia é sábio;', 'Quem é sábio sabe;']::text[]),
  ('la-pt', 'la-u165', 'frase', 'A1', array['frase de uso']::text[], 'la-p139', '9728dbfc', array['Acredita em mim, não ousarei;', 'Acredita em mim, não ousarás;', 'Acredita em mim, não ousaste;', 'Acreditai em mim, não ousareis;', 'Acredito em ti, não ousarás;']::text[]),
  ('la-pt', 'la-u166', 'frase', 'A1', array['frase de uso']::text[], 'la-p142', '29f43899', array['Os que crerem não se apressem.', 'Quem crer não se apresse.', 'Quem crer não se apressou.', 'Quem creu não se apressa.', 'Quem não crer se apresse.']::text[]),
  ('la-pt', 'la-u167', 'frase', 'A1', array['frase de uso']::text[], 'la-p144', '04491756', array['Não temos vinho.', 'Não tinham vinho.', 'Não têm vinho.', 'Não têm vinhos.', 'O vinho não os tem.']::text[]),
  ('la-pt', 'la-u168', 'frase', 'A1', array['frase de uso']::text[], 'la-p146', '979a4954', array['Ai da minha mãe!', 'Ai de mim, minha mãe!', 'Ai de mim, nossa mãe!', 'Ai de nós, minha mãe!', 'Ai de ti, minha mãe!']::text[]),
  ('la-pt', 'la-u169', 'frase', 'A1', array['frase de uso']::text[], 'la-p147', '10a037e8', array['A necessidade de combater, da qual fugis, nos seguirá.', 'A necessidade de combater, da qual fugis, vos seguia.', 'A necessidade de combater, da qual fugis, vos seguirá.', 'A necessidade de combater, que vos foge, vos seguirá.', 'Seguireis a necessidade de combater, da qual fugis.']::text[]),
  ('la-pt', 'la-u170', 'frase', 'A1', array['frase de uso']::text[], 'la-p148', 'f70b41c8', array['A alma é boa, e o corpo, e a fortuna.', 'Havia bens da alma, havia do corpo, havia da fortuna.', 'Há bens da alma, há do corpo, há da fortuna.', 'Há bens para a alma, para o corpo, para a fortuna.', 'Há o bem da alma, há o do corpo, há o da fortuna.']::text[]),
  ('la-pt', 'la-u171', 'frase', 'A1', array['frase de uso']::text[], 'la-p149', '92d653b8', array['Quanto ao que resta, ajudemos os deuses!', 'Quanto ao que resta, os deuses ajudam!', 'Quanto ao que resta, os deuses ajudaram!', 'Quanto ao que resta, que o deus ajude!', 'Quanto ao que resta, que os deuses ajudem!']::text[]),
