  ('la-pt', 'la-u173', 'frase', 'A1', array['frase de uso']::text[], 'la-p153', '29ffac23', array['A fábula do lobo.', 'Ao lobo, a fábula.', 'O lobo na fábula.', 'O lobo para dentro da fábula.', 'Os lobos na fábula.']::text[]),
  ('la-pt', 'la-u174', 'frase', 'A1', array['frase de uso']::text[], 'la-p154', '1321a09c', array['O homem te verá, pois, se quiseres.', 'Verei, pois, o homem, se quiser.', 'Verás, pois, o homem, se quiseres.', 'Verás, pois, os homens, se quiseres.', 'Viste, pois, o homem, se quiseste.']::text[]),
