  ('la-pt', 'la-u176', 'frase', 'A1', array['frase de uso']::text[], 'la-p156', 'db9a4709', array['Eu estava pronto.', 'Eu estou pronto.', 'Eu preparei.', 'Nós estamos prontos.', 'Tu estás pronto.']::text[]),
  ('la-pt', 'la-u177', 'frase', 'A1', array['frase de uso']::text[], 'la-p157', '9fe0e5af', array['Pois a guerra foi do Senhor.', 'Pois a guerra foi para o Senhor.', 'Pois a guerra será do Senhor.', 'Pois as guerras foram do Senhor.', 'Pois o Senhor foi da guerra.']::text[]),
  ('la-pt', 'la-u178', 'frase', 'A1', array['frase de uso']::text[], 'la-p158', '561e3e38', array['Se erraste, ensina-me tu;', 'Se errei, ensina-me tu;', 'Se errei, ensinai-me vós;', 'Se errei, eu te ensino;', 'Se erro, ensina-me tu;']::text[]),
  ('la-pt', 'la-u179', 'frase', 'A1', array['frase de uso']::text[], 'la-p159', 'f30d325d', array['Não quer aprender.', 'O querer não aprende.', 'O querer não se aprende.', 'O querer não se aprendia.', 'Os quereres não se aprendem.']::text[]),
  ('la-pt', 'la-u180', 'frase', 'A1', array['frase de uso']::text[], 'la-p160', '2226929a', array['Dirão bem todas as coisas.', 'Disse bem todas as coisas.', 'Disseram bem de todos.', 'Disseram bem todas as coisas.', 'Todas as coisas disseram bem.']::text[]),
  ('la-pt', 'la-u181', 'frase', 'A1', array['frase de uso']::text[], 'la-p161', '2ab223b3', array['a pátria nos foge;', 'eu fujo da pátria;', 'nós fugimos da pátria;', 'nós fugimos para a pátria;', 'nós fugíamos da pátria;']::text[]),
  ('la-pt', 'la-u183', 'frase', 'A1', array['frase de uso']::text[], 'la-p163', 'c50f969b', array['Nós, portanto, erramos muito.', 'Tu, portanto, erras muito.', 'Vós, portanto, errais muito.', 'Vós, portanto, errastes muito.', 'Vós, portanto, erráveis muito.']::text[]),
  ('la-pt', 'la-u184', 'frase', 'A1', array['frase de uso']::text[], 'la-p164', 'e535436f', array['as armas nos odeiam;', 'eu odeio as armas;', 'nós odiamos as armas;', 'nós odiaremos as armas;', 'nós odiávamos as armas;']::text[]),
  ('la-pt', 'la-u185', 'frase', 'A1', array['frase de uso']::text[], 'la-p165', 'aa47ee42', array['faze tudo para a glória de Deus.', 'fazei tudo para a glória de Deus.', 'fazeis tudo para a glória de Deus.', 'fizestes tudo para a glória de Deus.', 'tudo faz a glória de Deus.']::text[]),
  ('la-pt', 'la-u186', 'frase', 'A1', array['frase de uso']::text[], 'la-p166', '60d660d0', array['Talvez eu não venha.', 'Talvez não tenha vindo.', 'Talvez não venha.', 'Talvez não venham.', 'Talvez não viesse.']::text[]),
  ('la-pt', 'la-u187', 'frase', 'A1', array['frase de uso']::text[], 'la-p167', '7a60cbfc', array['Todos procuram a arma.', 'Todos procuram as armas.', 'Todos procuraram as armas.', 'Todos procurarão as armas.', 'Todos procuravam as armas.']::text[]),
  ('la-pt', 'la-u189', 'frase', 'A1', array['frase de uso']::text[], 'la-p169', '1bcf449d', array['e o deus sente isso;', 'e o deus sentirá isso;', 'e o deus sentiu isso;', 'e os deuses sentem isso;', 'e tu, ó deus, sentes isso;']::text[]),
  ('la-pt', 'la-u190', 'frase', 'A1', array['frase de uso']::text[], 'la-p170', 'ecb3c0b3', array['Estas coisas me torturam.', 'Estas coisas me torturaram.', 'Estas coisas me torturarão.', 'Estas coisas te torturam.', 'Eu torturo estas coisas.']::text[]),
  ('la-pt', 'la-u191', 'frase', 'A1', array['frase de uso']::text[], 'la-p171', '9a9ae2d3', array['Por que, então, ele não creu em vós?', 'Por que, então, não credes nele?', 'Por que, então, não crestes nele?', 'Por que, então, não crestes neles?', 'Por que, então, não crês nele?']::text[]),
  ('la-pt', 'la-u192', 'frase', 'A1', array['frase de uso']::text[], 'la-p172', 'd6565867', array['Diz-me: quem levarás, ó rainha das aves?', 'Diz-me: quem levas, ó rainha das aves?', 'Diz-me: quem levavas, ó rainha das aves?', 'Diz-me: quem te leva, ó rainha das aves?', 'Dizei-me: quem levais, ó rainhas das aves?']::text[]),
  ('la-pt', 'la-u193', 'frase', 'A1', array['frase de uso']::text[], 'la-p173', 'd240d4f5', array['Eu vi e me alegrei.', 'Tu viste e ele se alegrou.', 'Tu viste e te alegras.', 'Tu viste e te alegraste.', 'Vós vistes e vos alegrastes.']::text[]),
  ('la-pt', 'la-u194', 'frase', 'A1', array['frase de uso']::text[], 'la-p174', '6c2324b1', array['Porque vieram dias sobre ti:', 'Porque virá um dia sobre ti:', 'Porque virão dias sobre mim:', 'Porque virão dias sobre ti:', 'Porque vêm dias sobre ti:']::text[]),
  ('la-pt', 'la-u195', 'frase', 'A1', array['frase de uso']::text[], 'la-p175', '650a2619', array['Os deuses e tu me deram o que quero, se mereci.', 'Que os deuses e tu me deem o que quero, se mereceres.', 'Que os deuses e tu me deem o que quero, se mereci.', 'Que os deuses e tu me deem o que quero, se mereço.', 'Que os deuses e tu te deem o que queres, se mereceste.']::text[]),
  ('la-pt', 'la-u196', 'frase', 'A1', array['frase de uso']::text[], 'la-p176', 'c4d41178', array['eu carregarei e salvarei.', 'eu carregava e salvava.', 'eu carrego e salvo.', 'eu carreguei e salvei.', 'tu carregarás e salvarás.']::text[]),
  ('la-pt', 'la-u197', 'frase', 'A1', array['frase de uso']::text[], 'la-p177', '1d3bf784', array['Estava bem: Troia ressurgia;', 'Está bem: Troia ressurge;', 'Está bem: Troia ressurgirá;', 'Está bem: Troia ressurgiu;', 'Está bem: tu ressurges, Troia;']::text[]),
  ('la-pt', 'la-u198', 'frase', 'A1', array['frase de uso']::text[], 'la-p178', 'd25bf7fc', array['Fui e vim a vós.', 'Ide e vinde a mim.', 'Irei e virei a vós.', 'Vou e venho a vós.', 'Vou e venho de vós.']::text[]),
  ('la-pt', 'la-u200', 'frase', 'A1', array['frase de uso']::text[], 'la-p180', 'b8e27cba', array['Eu estarei nas mesmas armas.', 'Eu estive na mesma arma.', 'Eu estive nas mesmas armas.', 'Eu estou nas mesmas armas.', 'Tu estiveste nas mesmas armas.']::text[]),
  ('la-pt', 'la-u201', 'frase', 'A1', array['frase de uso']::text[], 'la-p181', '4fb8e7e7', array['Apascenta o meu cordeiro.', 'Apascenta os meus cordeiros.', 'Apascentai os meus cordeiros.', 'Apascentei os meus cordeiros.', 'Os meus cordeiros apascentam.']::text[]),
  ('la-pt', 'la-u202', 'frase', 'A1', array['frase de uso']::text[], 'la-p182', '295b1c9a', array['A minha sede era sã.', 'A minha sede é sã.', 'Que a minha sede seja sã.', 'Que a tua sede seja sã.', 'Que as minhas sedes sejam sãs.']::text[]),
  ('la-pt', 'la-u203', 'frase', 'A1', array['frase de uso']::text[], 'la-p183', 'c179a694', array['e agora viemos a vós, forçados pela necessidade.', 'e agora vieste a mim, forçado pela necessidade.', 'e agora viestes a mim, forçados pela necessidade.', 'e agora viestes a mim, forçando a necessidade.', 'e agora vindes a mim, forçados pela necessidade.']::text[]),
  ('la-pt', 'la-u205', 'frase', 'A1', array['frase de uso']::text[], 'la-p185', '8159c64a', array['E eu vim ao Senhor e fiquei de pé:', 'E o Senhor veio e ficou de pé:', 'E o Senhor vem e fica de pé:', 'E o Senhor virá e ficará de pé:', 'E vieram os senhores e ficaram de pé:']::text[]),
  ('la-pt', 'la-u206', 'frase', 'A1', array['frase de uso']::text[], 'la-p186', '1bbba442', array['De longe eu apareci ao Senhor.', 'De longe o Senhor me aparecerá.', 'De longe o Senhor me apareceu.', 'De longe o Senhor te apareceu.', 'De longe os senhores me apareceram.']::text[]),
  ('la-pt', 'la-u207', 'frase', 'A1', array['frase de uso']::text[], 'la-p187', '1bf7e4dc', array['nem era inferior a vós.', 'nem sois inferiores a mim.', 'nem sou inferior a ti.', 'nem sou inferior a vós.', 'nem és inferior a nós.']::text[]),
  ('la-pt', 'la-u208', 'frase', 'A1', array['frase de uso']::text[], 'la-p188', '3a8950db', array['Então verei, e transbordarei.', 'Então vereis, e transbordareis.', 'Então verás, e transbordarás.', 'Então viste, e transbordaste.', 'Então vês, e transbordas.']::text[]),
  ('la-pt', 'la-u209', 'frase', 'A1', array['frase de uso']::text[], 'la-p190', 'b91c92ca', array['E foi repelido pelo perverso.', 'E o perverso repeliu.', 'E repele o perverso.', 'E repeliu o perverso.', 'E repeliu os perversos.']::text[]),
  ('la-pt', 'la-u213', 'frase', 'A1', array['frase de uso']::text[], 'la-p194', 'f42f958e', array['O amor era para mim a causa de seguir.', 'O amor é para mim a causa de seguir.', 'O amor é para mim a causa de ser seguido.', 'O amor é para ti a causa de seguir.', 'Os amores são para mim a causa de seguir.']::text[]),
  ('la-pt', 'la-u214', 'frase', 'A1', array['frase de uso']::text[], 'la-p195', 'a0371e7a', array['A Dolópia levou a guerra.', 'Leva a guerra à Dolópia.', 'Levaram a guerra à Dolópia.', 'Levou a guerra da Dolópia.', 'Levou a guerra à Dolópia.']::text[]),
