  ('la-pt', 'la-u217', 'frase', 'A1', array['frase de uso']::text[], 'la-p198', 'bb9a5bbe', array['A mim, ao menos, parece que foi turbulento.', 'A mim, ao menos, parecem que vão ser turbulentos.', 'A mim, ao menos, pareciam que iam ser turbulentos.', 'Eles, ao menos, me veem turbulento.', 'Eu, ao menos, pareço que vou ser turbulento.']::text[]),
  ('la-pt', 'la-u218', 'frase', 'A1', array['frase de uso']::text[], 'la-p199', 'ed82756f', array['A água te viu, e temeu.', 'As águas te veem, e temem.', 'As águas te verão, e temerão.', 'As águas te viram, e temeram.', 'Tu viste as águas, e temeste.']::text[]),
