  ('la-pt', 'la-u222', 'frase', 'A1', array['frase de uso']::text[], 'la-p203', '59c4a2c1', array['Não temer o homem, nem o deus.', 'Não temer os homens, nem os deuses.', 'Não temeram os homens, nem os deuses.', 'Não temo os homens, nem os deuses.', 'Os homens não temem os deuses.']::text[]),
